SELECT (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='bk_agent' AND ((table_name='agent_orchestration_run' AND column_name IN ('run_id','user_id','request_json','lease_owner','lease_until_ms')) OR (table_name='agent_tool_invocation' AND column_name IN ('run_id','call_id','capability_id','arguments_hash','arguments_json','status','result_json','remote_association_json','updated_at_ms')) OR (table_name='agent_skill_snapshot' AND column_name IN ('run_id','snapshot_id','owner','skill_name','skill_version','content_hash','snapshot_json'))))=21 AND (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='bk_agent' AND table_name IN ('agent_orchestration_run','agent_tool_invocation','agent_skill_snapshot') AND engine='InnoDB')=3;
